    "id": "MessageTagProperties",
    "type": "object",
    "properties": {
      "tag": {
        "type": "string",
        "optional": true,
        "description": "Human-readable tag name."
      },
      "color": {
        "type": "string",
        "pattern": "^#[0-9a-fA-F]{6}",
        "optional": true,
        "description": "Tag color in upper case hex format (i.e.: <var>#000080</var> for navy blue)."
      },
      "ordinal": {
        "type": "string",
        "optional": true,
        "description": "A custom sort string."
      }
    }
  },
  {
    "id": "TagsDetail",
    "type": "object",
    "description": "Used for filtering messages by tag in various methods. Note that functions using this type may have a partial implementation.",
    "properties": {
      "tags": {
        "type": "object",
        "description": "A <em>dictionary object</em> with one or more filter condition as <em>key-value</em> pairs, the <em>key</em> being the tag to filter on, and the <em>value</em> being a boolean expression, requesting whether a message must include (<var>true</var>) or exclude (<var>false</var>) the tag. For a list of available tags, call the $(ref:messages.tags.list) method.",
        "patternProperties": {
          ".*": {
            "type": "boolean"
          }
        }
      },
      "mode": {
        "type": "string",
        "description": "Whether <var>all</var> of the tag filters must apply, <var>any</var> of them, or <var>none</var>. The <var>none</var> mode ignores the provided filters and selects only messages without any tags.",
        "enum": ["all", "any", "none"]
      }
    }
  }
],
"events": [
  {
    "name": "onCreated",
    "permissions": ["messagesTagsList"],
    "type": "function",
    "description": "Fired when a new message tag has been created.",
    "parameters": [
      {
        "name": "tag",
        "$ref": "messages.tags.MessageTag"
      }
    ]
  },
  {
    "name": "onUpdated",
    "permissions": ["messagesTagsList"],
    "type": "function",
    "description": "Fired when one or more properties of a message tag have been updated.",
    "parameters": [
      {
        "type": "string",
        "name": "key",
        "description": "Unique tag identifier of the updated message tag."
      },
      {
        "name": "changedProperties",
        "$ref": "messages.tags.MessageTagProperties",
        "description": "The changed message tag properties."
      },
      {
        "name": "oldProperties",
        "$ref": "messages.tags.MessageTagProperties",
        "description": "The old values of the changed message tag properties."
      }
    ]
  },
  {
    "name": "onDeleted",
    "type": "function",
    "description": "Fired when a message tag has been deleted.",
    "permissions": ["messagesTagsList"],
    "parameters": [
      {
        "type": "string",
        "name": "key",
        "description": "Unique tag identifier of the deleted message tag."
      }
    ]
  }
],
